import { lit, MaterialPlugin, materialType } from "@dylanebert/shallot/standard/rendering";
import tgpu from "typegpu";
import * as d from "typegpu/data";
import * as std from "typegpu/std";

/** Bands per unit of distance along the stripe direction. */
export const stripeFrequency = 3;
/** Bands that pass a fixed point per second. */
export const stripeSpeed = 0.6;
/** Diagonal direction the bands march along, in the cube's local space. */
export const stripeDirection = d.vec3f(1, 1, 0.35);

/** 0 or 1: which of the two band colors covers a local-space point at a time. */
export const stripeBand = tgpu.fn(
    [d.vec3f, d.f32],
    d.f32,
)((localPos, time) => {
    "use gpu";
    const phase = std.dot(localPos, stripeDirection) * stripeFrequency - time * stripeSpeed;
    return std.step(0.5, std.fract(phase));
});

export const StripeParameters = d.struct({
    time: d.f32,
    colorA: d.vec3f,
    colorB: d.vec3f,
});

/** Lit diagonal bands in local space, so they run continuously across the cube's faces and
 * march along stripeDirection as the row's time advances. */
export const StripeMaterial = materialType({
    name: "MovingStripes",
    parameters: StripeParameters,
    defaults: { time: 0, colorA: d.vec3f(0.04, 0.035, 0.03), colorB: d.vec3f(0.72, 0.4, 0.05) },
    fragmentInputs: { localPos: true },
    fragment: (ctx) => {
        "use gpu";
        const band = stripeBand(ctx.localPos, ctx.parameters.time);
        const color = std.mix(ctx.parameters.colorA, ctx.parameters.colorB, band);
        return d.vec4f(lit(color, ctx.worldNormal), 1);
    },
});

export const StripePlugin = MaterialPlugin(StripeMaterial);

