import { expect, test } from "bun:test";
import { createApp, Transform } from "@dylanebert/shallot";
import * as d from "typegpu/data";
import { Stripes, Welcome, WelcomeCube } from "./index";
import { StripeMaterial, stripeBand } from "./stripes";

test("the stripe material's time advances when the world steps", async () => {
    const app = await createApp({ defaults: false, plugins: [Welcome] });
    try {
        const { world } = app;
        const stripes = world.resource(Stripes);
        world.step(1 / 60);
        world.step(1 / 60);
        expect(stripes.time).toBeCloseTo(2 / 60, 6);
        expect(world.resource(StripeMaterial).get(stripes.material!)!.time).toBeCloseTo(2 / 60, 6);
    } finally {
        app.dispose();
    }
});

test("the cube stays put; only its pattern moves", async () => {
    const app = await createApp({ defaults: false, plugins: [Welcome] });
    try {
        const cube = [...app.world.query([WelcomeCube])][0]!;
        const rotation = app.world.storage(Transform).rotation;
        const before = [rotation.y.get(cube), rotation.w.get(cube)];
        app.world.step(1 / 60);
        expect([rotation.y.get(cube), rotation.w.get(cube)]).toEqual(before);
    } finally {
        app.dispose();
    }
});

const line = (time: number) =>
    Array.from({ length: 100 }, (_, i) => stripeBand(d.vec3f(-0.5 + i / 99, 0, 0.5), time));

test("a face shows several bands, and they shift over time", () => {
    const now = line(0);
    const edges = now.filter((value, i) => i > 0 && value !== now[i - 1]).length;
    expect(edges).toBeGreaterThanOrEqual(3);
    expect(line(0.4)).not.toEqual(now);
    expect(line(1 / 0.6)).toEqual(now);
});
