import { expect, setDefaultTimeout, test } from "bun:test";
import { Camera } from "@dylanebert/shallot";
import { attachTexture, captureTexture } from "@dylanebert/shallot/rendering";
import { TIMEOUT } from "@dylanebert/shallot/testing";
import { openGpuApp } from "@dylanebert/shallot/testing/gpu";
import { Welcome } from "../src/welcome";

setDefaultTimeout(TIMEOUT.node);

const size = 128;

test("the rendered cube shows bands that move between frames", async () => {
    const app = await openGpuApp({ plugins: [Welcome] });
    try {
        const { world } = app;
        const camera = [...world.query([Camera])][0]!;
        attachTexture(world, camera, { width: size, height: size });
        world.step(0);
        world.step(0);
        const first = (await captureTexture(world, camera)).rgba;
        world.step(0.4);
        world.step(0);
        const second = (await captureTexture(world, camera)).rgba;
        if (process.env.SHALLOT_CAPTURE_DIR) {
            const { writeFileSync } = await import("node:fs");
            writeFileSync(`${process.env.SHALLOT_CAPTURE_DIR}/stripes-a.rgba`, first);
            writeFileSync(`${process.env.SHALLOT_CAPTURE_DIR}/stripes-b.rgba`, second);
        }
        // central region covers the cube
        let bright = 0;
        let dark = 0;
        let changed = 0;
        for (let y = 44; y < 84; y++)
            for (let x = 44; x < 84; x++) {
                const i = (y * size + x) * 4;
                const r = first[i]!;
                if (r > 90) bright++;
                if (r < 40) dark++;
                if (Math.abs(r - second[i]!) > 30) changed++;
            }
        console.log({ bright, dark, changed });
        expect(bright, "orange band pixels").toBeGreaterThan(150);
        expect(dark, "dark band pixels").toBeGreaterThan(150);
        expect(changed, "pixels that changed as the bands moved").toBeGreaterThan(150);
    } finally {
        app.dispose();
    }
});
